    {
      "id": 1,
      "claim": "For a concave mirror, the mirror equation is 1/f = 1/do + 1/di, where f > 0.",
      "evidence": "Standard thin‑mirror formula for spherical mirrors.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The magnification is m = -di/do.",
      "evidence": "Definition of linear magnification for mirrors.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "When the object is far away (do → ∞), 1/do → 0, so 1/di = 1/f and di = f.",
      "evidence": "Apply the mirror equation from step 1 with do → ∞.",
      "weight": 0.10,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "With do → ∞, the magnification m = -di/do → 0, so the image is very small.",
      "evidence": "Use m = -di/do from step 2 with di = f (finite) and do → ∞.",
      "weight": 0.10,
      "depends_on": [2,3]
    },
    {
      "id": 5,
      "claim": "As the object moves toward the focal point (do decreases toward f from above), 1/di = 1/f – 1/do becomes a small positive number, so di → ∞; the image moves farther from the mirror.",
      "evidence": "Algebraic limit of the mirror equation as do → f⁺.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 6,
      "claim": "When di grows without bound while do stays finite (do > f), the magnitude of magnification |m| = di/do becomes very large, so the image height increases (gets taller).",
      "evidence": "From step 2, m = -di/do; as di → ∞, |m| → ∞.",
      "weight": 0.20,
      "depends_on": [2,5]
    },
    {
      "id": 7,
      "claim": "Therefore, as the object moves from far away to near the focal point, the image moves away from the mirror and becomes taller.",
      "evidence": "Combine the direction change (step 5) and size change (step 6).",
      "weight": 0.10,
      "depends_on": [5,6]
    }
  ],
  "answer": "B",
  "confidence": 0.97,
